# Generated by build.py from recipe.yml for recipe dns-look-up-a-name. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'zones/.surl/dns', 'transfers/.surl/dns', 'bad/.surl/dns' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'zones/.surl/dns/example.com.zone'), "`$ORIGIN example.com.`n`$TTL 3600`n@     IN SOA   ns1.example.com. admin.example.com. 1 7200 3600 1209600 300`n@     IN NS    ns1.example.com.`n@     IN MX    10 mail.example.com.`nns1   IN A     127.0.0.1`nwww   IN A     192.0.2.10`nmail  IN A     192.0.2.25`nftp   IN CNAME www`n")
[IO.File]::WriteAllText((Join-Path $PWD 'transfers/.surl/dns/example.com.zone'), "`$ORIGIN example.com.`n`$TTL 3600`n@     IN SOA   ns1.example.com. admin.example.com. 1 7200 3600 1209600 300`n@     IN NS    ns1.example.com.`n@     IN MX    10 mail.example.com.`nns1   IN A     127.0.0.1`nwww   IN A     192.0.2.10`nmail  IN A     192.0.2.25`nftp   IN CNAME www`n")
[IO.File]::WriteAllText((Join-Path $PWD 'bad/.surl/dns/example.net.zone'), "this is not a zone`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'zones', 'dns://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe dns://127.0.0.1:8080/www.example.com } finally { Stop-Process $server0 }
